 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [[bg for _ in range(w)] for _ in range(h)]
    # The non-background rectangular objects have sparse corruption/noise;
    # recover each rectangle from its dense color's bounding box.
    for color, n in counts.items():
        if color == bg or n < 8:
            continue
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        area = (r1-r0+1) * (c1-c0+1)
        if area >= 12 and n/area >= 0.35:
            for r in range(r0, r1+1):
                for c in range(c0, c1+1):
                    out[r][c] = color
    return out
